import json
from taskbook.api import make_multi_server, serve_in_thread

import urllib.error, urllib.parse, urllib.request
OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))
class _NR(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None
OPENNR = urllib.request.build_opener(urllib.request.ProxyHandler({}), _NR())
def raw(server, method, path, form=None, headers=None, follow=True):
    url = "http://127.0.0.1:%d%s" % (server.server_address[1], path)
    data = None
    hdrs = dict(headers or {})
    if form is not None:
        data = urllib.parse.urlencode(form).encode("utf-8")
        hdrs["Content-Type"] = "application/x-www-form-urlencoded"
    req = urllib.request.Request(url, data=data, method=method, headers=hdrs)
    try:
        with (OPENER if follow else OPENNR).open(req) as resp:
            return resp.status, resp.headers.get_content_type(), resp.read().decode("utf-8")
    except urllib.error.HTTPError as err:
        return err.code, err.headers.get_content_type(), err.read().decode("utf-8")

def call_json(server, method, path, body=None, headers=None):
    url = "http://127.0.0.1:%d%s" % (server.server_address[1], path)
    data = json.dumps(body).encode() if body is not None else None
    hdrs = {"Content-Type": "application/json"}
    hdrs.update(headers or {})
    req = urllib.request.Request(url, data=data, method=method, headers=hdrs)
    try:
        with OPENER.open(req) as resp:
            return resp.status, json.loads(resp.read().decode())
    except urllib.error.HTTPError as err:
        return err.code, json.loads(err.read().decode())
server = make_multi_server()
serve_in_thread(server)
try:
    status, ctype, _ = raw(server, "GET", "/")
    print("anonymous GET /:", status, ctype)
    call_json(server, "POST", "/register",
              {"username": "ada", "password": "password-1"})
    _, payload = call_json(server, "POST", "/login",
                           {"username": "ada", "password": "password-1"})
    auth = {"Authorization": "Bearer " + payload["token"]}
    call_json(server, "POST", "/tasks", {"title": "Ada task"},
              headers=auth)
    status, ctype, body = raw(server, "GET", "/", headers=auth)
    print("authed GET /:", status, ctype,
          "| sees own task:", "Ada task" in body)
finally:
    server.shutdown(); server.server_close()

import os, re, subprocess, sys
root = "/home/hatch/workspace/.flipbook-build/project"
def key(rel):
    if "/" not in rel:
        return (0, rel)
    if rel.startswith("taskbook/"):
        return (1, rel)
    if rel.startswith("tests/fixtures/"):
        return (3, rel)
    return (2, rel)
files = []
for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d not in ("__pycache__", ".pytest_cache")]
    for fn in filenames:
        files.append(os.path.relpath(os.path.join(dirpath, fn), root))
total = 0
for rel in sorted(files, key=key):
    with open(os.path.join(root, rel), encoding="utf-8") as fh:
        n = sum(1 for _ in fh)
    total += n
    print("%s: %d" % (rel, n))
print("total lines:", total)
r = subprocess.run([sys.executable, "-m", "pytest", "-q"], cwd=root,
                   capture_output=True, text=True)
out = r.stdout + r.stderr
p = re.search(r"(\d+) passed", out)
f = re.search(r"(\d+) failed", out)
print("%s passed, %s failed" % (p.group(1) if p else 0, f.group(1) if f else 0))

